@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VeterinariansView extends VerticalLayout {

    private final transient VetRepository repository;

    public VeterinariansView(VetRepository repository) {
        this.repository = repository;
        setSizeFull();

        H2 heading = new H2("Veterinarians");
        heading.addClassNames(LumoUtility.Margin.NONE);

        Grid<Vet> grid = new Grid<>();
        grid.setSizeFull();
        grid.setSelectionMode(Grid.SelectionMode.NONE);
        grid.getElement().setAttribute("aria-label", "Veterinarians");
        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
        grid.addColumn(vet -> vet.specialties().isEmpty()
                        ? "none" : String.join(", ", vet.specialties()))
                .setHeader("Specialties").setKey("specialties").setFlexGrow(2);
        grid.setItems(query -> loadOrShowError(
                        () -> this.repository.findPage(query.getOffset(), query.getLimit()), Stream.empty()),
                query -> loadOrShowError(() -> this.repository.count(), 0));
        add(heading, grid);
        expand(grid);
    }

    private <T> T loadOrShowError(Supplier<T> load, T empty) {
        try {
            return load.get();
        } catch (RuntimeException exception) {
            // Lazy callbacks also run after navigation, outside the router's error handling.
            // The RPC helper requires an exact match to the error view's Exception type.
            if (!ErrorHandlerUtil.handleErrorByRedirectingToErrorView(
                    new Exception(exception.getMessage(), exception))) {
                throw exception;
            }
            return empty;
        }
    }
}
