+
+/** UC-002, using the real PostgreSQL queries and the live component tree. */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void menuOpensAnonymousDirectoryWithNamesAndOrderedSpecialties() {
+        navigate(WelcomeView.class);
+        test(assertDoesNotThrow(() -> find(SideNav.class).single(), "Expected main menu"))
+                .clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        var grid = test(directory());
+        assertEquals(6, grid.size());
+        assertEquals("First Name", grid.getHeaderCell(0));
+        assertEquals("Last Name", grid.getHeaderCell(1));
+        assertEquals("Specialties", grid.getHeaderCell(2));
+        assertEquals("James", grid.getCellText(0, 0));
+        assertEquals("Carter", grid.getCellText(0, 1));
+        assertEquals("none", grid.getCellText(0, 2));
+        assertEquals("Linda", grid.getCellText(1, 0));
+        assertEquals("Douglas", grid.getCellText(1, 1));
+        assertEquals("dentistry, surgery", grid.getCellText(1, 2));
+        assertEquals("radiology", grid.getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS));
+        assertEquals(5, dsl.fetchCount(VET_SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryStillShowsGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VeterinariansView.class);
+        assertEquals(0, test(directory()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void lazyProviderFetchesBoundedPagesWithoutSkippingDuplicateNames() {
+        for (int i = 0; i < 117; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Alex", "Smith").execute();
+        }
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = directory();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertFalse(grid.isAllRowsVisible());
+        assertEquals(123, grid.getDataProvider().size(new Query<>()));
+        clearInvocations(repository);
+
+        List<Vet> loaded = new ArrayList<>();
+        for (int offset = 0; offset < 123; offset += 25) {
+            var page = grid.getDataProvider().fetch(new Query<>(offset, 25, List.of(), null, null)).toList();
+            assertEquals(Math.min(25, 123 - offset), page.size());
+            loaded.addAll(page);
+            verify(repository).findPage(offset, 25);
+        }
+        assertEquals(123, loaded.stream().map(Vet::id).distinct().count());
+        assertEquals(List.of("Carter", "Douglas", "Jenkins", "Leary", "Ortega"),
+                loaded.subList(0, 5).stream().map(Vet::lastName).toList());
+        assertTrue(grid.getDataProvider().fetch(new Query<>(123, 25, List.of(), null, null)).findAny().isEmpty());
+        assertEquals(loaded.subList(25, 50),
+                grid.getDataProvider().fetch(new Query<>(25, 25, List.of(), null, null)).toList());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorWithoutDirectory() {
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = directory();
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).count();
+        grid.getDataProvider().size(new Query<>());
+        assertErrorReplacesDirectory();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterPageFailureShowsApplicationErrorWithoutStaleRows() {
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = directory();
+        assertEquals(6, test(grid).size());
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).findPage(anyInt(), anyInt());
+        grid.getDataProvider().fetch(new Query<>(2, 2, List.of(), null, null)).toList();
+        assertErrorReplacesDirectory();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> directory() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarians grid");
+    }
+
+    private void assertErrorReplacesDirectory() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(), "Expected application error view");
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must not remain visible");
+        assertDoesNotThrow(() -> find(SideNav.class).single(), "Navigation must remain available");
+    }
